script:
(function () {
  'use strict';
  // Credit card roll-down: freeze today's total payment and keep paying it until every card is gone.
  // Card minimums are recalculated each month from the balance, so they shrink as you pay:
  //   "interest plus X%": minimum = interest + X% of the balance before interest;
  //   "X% of the balance": minimum = X% of the balance after interest;
  //   either way at least the floor amount, never more than what is owed, rounded to the cent.
  // Each month every open card is charged interest = balance x APR / 12 (rounded to the cent).
  //   Minimums only: each card pays its own shrinking minimum.
  //   Roll-down: the monthly payment is fixed at month 1's total minimums + the extra amount.
  //   Every open card gets its current minimum and everything left (the extra plus the amount
  //   the minimums have shrunk by, plus the minimums of cleared cards) goes to the target card -
  //   highest APR first or smallest balance first - spilling to the next card if it clears.
  // Verified (scratchpad b5debt/math2.test.js):
  //   one $1,000 card at 0% with a 10% minimum and $25 floor, roll-down -> fixed $100 a month,
  //   cleared in exactly 10 months; minimums only -> $100, $90, $81 ... until the $25 floor, a
  //   24 months, matching a hand loop;
  //   interest-plus-1% minimum on $5,000 at 24% -> first minimum $100 + $50 = $150 and the
  //   balance falls exactly 1% a month on minimums only (5,000 x 0.99^12 = $4,431.92 after a year);
  //   roll-down with a fixed $150 on that card matches the closed form n = -ln(1 - rB/P) / ln(1 + r)
  //   = 55.48 -> 56 months, interest within $0.10 of a direct level-payment simulation;
  //   total paid = starting balances + interest in both plans; every roll-down month pays exactly
  //   the fixed amount except the last; across 1,000 random card sets the roll-down never costs
  //   more interest or takes longer than minimums only.
  //   Default example (interest + 1%, $25 floor, $0 extra, highest APR first): fixed $362.89,
  //   56 months and $7,599.78 interest vs 247 months and $20,438.31 on minimums only.
  var MAX_MONTHS = 1200;
  var MAX_CARDS = 8;
  var DEFAULTS = [
    { name: 'Rewards card', balance: 4500, apr: 24.99 },
    { name: 'Store card', balance: 1800, apr: 28.99 },
    { name: 'Bank card', balance: 6200, apr: 19.49 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  // rule: { type: 'interest' | 'pct', pct (decimal), floor }
  function minimumDue(before, interest, rule) {
    var owed = before + interest;
    var m = rule.type === 'interest' ? interest + rule.pct * before : rule.pct * owed;
    return cents(Math.min(Math.max(m, rule.floor), owed));
  }

  function targetOrder(cards, order) {
    var idx = cards.map(function (c, i) { return i; });
    idx.sort(function (a, b) {
      var ca = cards[a], cb = cards[b];
      if (order === 'balance') return (ca.balance - cb.balance) || (cb.apr - ca.apr) || (a - b);
      return (cb.apr - ca.apr) || (ca.balance - cb.balance) || (a - b);
    });
    return idx;
  }

  // plan: 'minimums' | 'rolldown'. Returns totals, per-card payoff month, yearly rows.
  function simulate(cards, rule, extra, order, plan) {
    var n = cards.length, bal = cards.map(function (c) { return c.balance; });
    var seq = targetOrder(cards, order), cleared = cards.map(function () { return 0; });
    var targetPay = cards.map(function () { return 0; });
    var budget = 0;
    cards.forEach(function (c) { budget += minimumDue(c.balance, cents(c.balance * c.apr / 12), rule); });
    var firstMin = cents(budget);
    budget = cents(budget + extra);
    var interestTotal = 0, paidTotal = 0, years = [], yPaid = 0, yInt = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var i, mins = [], owedNow = [], avail = budget, open = 0;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) { mins.push(0); owedNow.push(0); continue; }
        var interest = cents(bal[i] * cards[i].apr / 12);
        mins.push(minimumDue(bal[i], interest, rule));
        bal[i] = cents(bal[i] + interest);
        owedNow.push(bal[i]);
        interestTotal += interest; yInt += interest;
      }
      if (plan === 'rolldown') {
        var focus = -1;
        for (var k = 0; k < n; k++) if (bal[seq[k]] > 0.005) { focus = seq[k]; break; }
        if (focus >= 0 && !targetPay[focus]) {
          var others = 0;
          for (i = 0; i < n; i++) if (i !== focus && bal[i] > 0.005) others += mins[i];
          targetPay[focus] = cents(Math.min(budget - others, bal[focus]));
        }
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var pay = plan === 'rolldown' ? Math.min(mins[i], avail) : mins[i];
        bal[i] = cents(bal[i] - pay); avail = cents(avail - pay); paidTotal += pay; yPaid += pay;
      }
      if (plan === 'rolldown') {
        for (k = 0; k < n && avail > 0.005; k++) {
          var j = seq[k];
          if (bal[j] <= 0.005) continue;
          var more = Math.min(avail, bal[j]);
          bal[j] = cents(bal[j] - more); avail = cents(avail - more); paidTotal += more; yPaid += more;
        }
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) { bal[i] = 0; if (!cleared[i] && owedNow[i] > 0) cleared[i] = m; } else open++;
      }
      var remaining = bal.reduce(function (s, b) { return s + b; }, 0);
      if (m % 12 === 0 || open === 0) {
        years.push({ year: Math.ceil(m / 12), paid: yPaid, interest: yInt, remaining: remaining });
        yPaid = 0; yInt = 0;
      }
      if (open === 0) return { paidOff: true, months: m, interest: interestTotal, paid: paidTotal, cleared: cleared, targetPay: targetPay, order: seq, budget: budget, firstMin: firstMin, years: years };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interestTotal, paid: paidTotal, cleared: cleared, targetPay: targetPay, order: seq, budget: budget, firstMin: firstMin, years: years };
  }

  // ---- Page ----
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addCardRow(c) {
    var list = document.getElementById('rdcCards');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-card-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Card');
    title.setAttribute('data-card-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-card-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'rdcName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'rdcName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = c.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('rdcBal' + n, 'Balance', c.balance, '$', true, '100'));
    pair.appendChild(numberField('rdcApr' + n, 'APR', c.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('rdcCards').querySelectorAll('[data-card-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-card-title]').textContent = 'Card ' + (i + 1);
      var rm = row.querySelector('[data-remove]');
      rm.disabled = rows.length <= 1;
      rm.setAttribute('aria-label', 'Remove card ' + (i + 1));
    });
    document.getElementById('rdcAdd').disabled = rows.length >= MAX_CARDS;
  }

  function readCards() {
    var out = [], ok = true;
    var rows = document.getElementById('rdcCards').querySelectorAll('[data-card-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-card-row');
      var name = document.getElementById('rdcName' + n).value.trim() || ('Card ' + (i + 1));
      var balEl = document.getElementById('rdcBal' + n), aprEl = document.getElementById('rdcApr' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e7, badApr = isNaN(apr) || apr < 0 || apr > 100;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      if (badBal || badApr) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100 });
    });
    return { ok: ok, cards: out };
  }

  function clearResults() {
    ['rdcBudget', 'rdcDate', 'rdcInterest', 'rdcMinDate', 'rdcMinInterest', 'rdcSaved'].forEach(function (id) { set(id, '–'); });
    ['rdcBudgetNote', 'rdcDateNote', 'rdcMinDateNote', 'rdcSavedNote'].forEach(function (id) { set(id, ''); });
    clearBody('rdcOrderBody'); clearBody('rdcYears');
  }

  function aprText(apr) { return (apr * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function update() {
    var error = document.getElementById('rdcError');
    var ruleType = document.getElementById('rdcRule').value === 'pct' ? 'pct' : 'interest';
    var pct = parseFloat(document.getElementById('rdcPct').value);
    var floorEl = document.getElementById('rdcFloor'), extraEl = document.getElementById('rdcExtra');
    var floor = floorEl.value.trim() === '' ? 0 : parseFloat(floorEl.value);
    var extra = extraEl.value.trim() === '' ? 0 : parseFloat(extraEl.value);
    var order = document.getElementById('rdcOrder').value === 'balance' ? 'balance' : 'apr';
    var input = readCards();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted cards: balances of $0 or more and APRs from 0 to 100%.';
    else if (!input.cards.length) problem = 'Enter at least one card with a balance above $0.';
    else if (isNaN(pct) || pct <= 0 || pct > 50) problem = 'Enter a minimum payment percentage above 0 and up to 50%.';
    else if (isNaN(floor) || floor < 0) problem = 'Enter a minimum payment floor of $0 or more.';
    else if (isNaN(extra) || extra < 0) problem = 'Enter a roll-down amount of $0 or more.';
    var cards = input.cards, rule = { type: ruleType, pct: pct / 100, floor: floor };
    if (!problem && ruleType === 'pct') {
      for (var k = 0; k < cards.length; k++) {
        if (rule.pct * (1 + cards[k].apr / 12) <= cards[k].apr / 12 + 1e-9) {
          problem = 'A minimum of ' + pct + '% of the balance does not cover the monthly interest on ' + cards[k].name + '. Use a higher percentage or the interest-plus rule.';
          break;
        }
      }
    }
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }

    var roll = simulate(cards, rule, extra, order, 'rolldown');
    var mins = simulate(cards, rule, 0, order, 'minimums');
    if (!roll.paidOff) {
      error.hidden = false;
      error.textContent = 'This fixed payment does not pay these cards off within 100 years. Add a roll-down amount.';
      clearResults();
      return;
    }
    error.hidden = true; error.textContent = '';

    set('rdcBudget', money.format(roll.budget));
    set('rdcBudgetNote', 'This month’s minimums of ' + money.format(roll.firstMin) + (extra > 0 ? ' plus ' + money.format(extra) + '.' : '.') + ' Keep paying this every month.');
    set('rdcDate', dateAfter(roll.months));
    set('rdcDateNote', 'Debt-free in ' + duration(roll.months) + '.');
    set('rdcInterest', money.format(roll.interest));
    if (mins.paidOff) {
      set('rdcMinDate', dateAfter(mins.months));
      set('rdcMinDateNote', duration(mins.months) + ', with ' + money.format(mins.interest) + ' interest.');
      set('rdcMinInterest', money.format(mins.interest));
      set('rdcSaved', money.format(Math.max(mins.interest - roll.interest, 0)));
      set('rdcSavedNote', mins.months > roll.months ? 'And debt-free ' + duration(mins.months - roll.months) + ' sooner.' : 'Same finish date as minimums only.');
    } else {
      set('rdcMinDate', 'Over 100 years');
      set('rdcMinDateNote', 'The shrinking minimums never clear these cards.');
      set('rdcMinInterest', 'Over ' + money.format(mins.interest));
      set('rdcSaved', 'Over ' + money.format(Math.max(mins.interest - roll.interest, 0)));
      set('rdcSavedNote', 'Interest on minimums only is counted for the first 100 years.');
    }

    var orderBody = clearBody('rdcOrderBody');
    roll.order.forEach(function (i, step) {
      var c = cards[i];
      addRow(orderBody, [String(step + 1), c.name, money.format(c.balance), aprText(c.apr),
        roll.targetPay[i] ? money.format(roll.targetPay[i]) + '/mo' : 'Cleared by its minimum',
        dateAfter(roll.cleared[i]) + ' (month ' + roll.cleared[i] + ')',
        mins.cleared[i] ? dateAfter(mins.cleared[i]) + ' (month ' + mins.cleared[i] + ')' : 'Over 100 years']);
    });

    var yearsBody = clearBody('rdcYears');
    var last = Math.max(roll.years.length, mins.years.length);
    for (var y = 0; y < last; y++) {
      var a = mins.years[y], b = roll.years[y];
      addRow(yearsBody, [String(y + 1),
        a ? money.format(a.paid) : '–', a ? money.format(a.remaining) : money.format(0),
        b ? money.format(b.paid) : '–', b ? money.format(b.remaining) : money.format(0)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addCardRow);
    var form = document.getElementById('rdcForm');
    document.getElementById('rdcRule').addEventListener('change', function () {
      // Suggest a typical percentage for the chosen rule before recalculating.
      document.getElementById('rdcPct').value = document.getElementById('rdcRule').value === 'pct' ? '3' : '1';
    });
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('rdcAdd').addEventListener('click', function () {
      if (document.getElementById('rdcCards').querySelectorAll('[data-card-row]').length >= MAX_CARDS) return;
      addCardRow({ name: '', balance: '', apr: '' });
      update();
    });
    update();
  });
})();
